package mission

// Shared conformance vectors (conformance/vectors/*.json), generated by the Python reference. These tests assert the Go
// port byte for byte; if a vector file is missing (the module was extracted from the repo) the tests skip.

import (
	"bytes"
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"testing"
)

func loadVectors(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "..", "conformance", "vectors", name))
	if err != nil {
		t.Skipf("conformance vectors not available: %v", err)
	}
	return b
}

// decodeNumbers decodes JSON keeping number text (json.Number), the only way int/float text survives.
func decodeNumbers(t *testing.T, b []byte, v any) {
	t.Helper()
	d := json.NewDecoder(bytes.NewReader(b))
	d.UseNumber()
	if err := d.Decode(v); err != nil {
		t.Fatal(err)
	}
}

type vecEvent struct {
	Seq       int             `json:"seq"`
	Ts        json.Number     `json:"ts"`
	Type      string          `json:"type"`
	MissionID string          `json:"mission_id"`
	Payload   json.RawMessage `json:"payload"`
	Prev      string          `json:"prev"`
	Hash      string          `json:"hash"`
	Canonical string          `json:"canonical"`
}

func (v vecEvent) payloadValue(t *testing.T) any {
	var p any
	decodeNumbers(t, v.Payload, &p)
	return p
}

func (v vecEvent) ts(t *testing.T) float64 {
	f, err := v.Ts.Float64()
	if err != nil {
		t.Fatal(err)
	}
	return f
}

func TestChainVectorsCanonicalAndHashAreByteIdenticalToPython(t *testing.T) {
	var doc struct {
		Cases []struct {
			Name   string     `json:"name"`
			Events []vecEvent `json:"events"`
		} `json:"cases"`
	}
	decodeNumbers(t, loadVectors(t, "chain.json"), &doc)
	if len(doc.Cases) == 0 {
		t.Fatal("no chain cases")
	}
	for _, c := range doc.Cases {
		for _, e := range c.Events {
			canon := string(chainCanonical(e.Seq, e.ts(t), e.Type, e.MissionID, e.payloadValue(t)))
			if canon != e.Canonical {
				t.Errorf("%s seq %d canonical differs:\n go: %s\n py: %s", c.Name, e.Seq, canon, e.Canonical)
			}
			if h := EntryHash(e.Prev, e.Seq, e.ts(t), e.Type, e.MissionID, e.payloadValue(t)); h != e.Hash {
				t.Errorf("%s seq %d hash %s want %s", c.Name, e.Seq, h, e.Hash)
			}
		}
	}
}

func eventFromVector(t *testing.T, raw json.RawMessage) *Event {
	t.Helper()
	ev, ok := decodeEventLine(raw) // the SAME path a log line takes on load
	if !ok {
		t.Fatalf("cannot decode %s", raw)
	}
	return ev
}

func TestTamperVectorsReportExactlyWhatPythonReports(t *testing.T) {
	var doc struct {
		Tamper []struct {
			Name   string            `json:"name"`
			Events []json.RawMessage `json:"events"`
			Expect ChainReport       `json:"expect"`
		} `json:"tamper"`
	}
	decodeNumbers(t, loadVectors(t, "chain.json"), &doc)
	if len(doc.Tamper) < 5 {
		t.Fatal("expected the tamper cases")
	}
	for _, c := range doc.Tamper {
		var evs []*Event
		for _, r := range c.Events {
			evs = append(evs, eventFromVector(t, r))
		}
		if got := VerifyChain(evs); got != c.Expect {
			t.Errorf("%s: got %+v want %+v", c.Name, got, c.Expect)
		}
	}
}

func TestAPythonWrittenLogLoadsAndVerifiesInGo(t *testing.T) {
	var doc struct {
		Cases []struct {
			Name   string            `json:"name"`
			Events []json.RawMessage `json:"events"`
		} `json:"cases"`
	}
	decodeNumbers(t, loadVectors(t, "chain.json"), &doc)
	for _, c := range doc.Cases {
		path := filepath.Join(t.TempDir(), "log.jsonl")
		var buf bytes.Buffer
		for _, r := range c.Events {
			if err := json.Compact(&buf, r); err != nil { // one event per line, number text untouched
				t.Fatal(err)
			}
			buf.WriteByte('\n')
		}
		if err := os.WriteFile(path, buf.Bytes(), 0o600); err != nil {
			t.Fatal(err)
		}
		s := NewEventStore(path)
		if rep := s.Verify(); !rep.OK || rep.Checked != len(c.Events) {
			t.Errorf("%s: %+v", c.Name, rep)
		}
	}
}

func TestGoWrittenLogRoundTripsAndEditsAreDetected(t *testing.T) {
	path := filepath.Join(t.TempDir(), "log.jsonl")
	s := NewEventStore(path)
	s.Append("MissionCreated", "m1", map[string]any{"goal": "pay", "n": 3})
	s.Append("NodeSucceeded", "m2", map[string]any{"amount": 100, "f": 1.5, "u": "é中😀", "tiny": 1e-7, "int": 7})
	s.Append("NodeSucceeded", "m1", map[string]any{"result": map[string]any{"amount": 100.0}})
	if rep := s.Verify(); !rep.OK || rep.Checked != 3 || rep.Unchained != 0 {
		t.Fatalf("in-memory: %+v", rep)
	}
	if rep := NewEventStore(path).Verify(); !rep.OK || rep.Checked != 3 {
		t.Fatalf("after reload: %+v", rep)
	}
	// the chain continues after a restart
	again := NewEventStore(path)
	head := again.Head("m1")
	ev := again.Append("NodeVerified", "m1", map[string]any{"node_id": "n"})
	if ev.Prev != head || !NewEventStore(path).Verify().OK {
		t.Fatalf("chain did not continue: prev=%q head=%q", ev.Prev, head)
	}
	// edit a payload on disk
	raw, _ := os.ReadFile(path)
	edited := bytes.Replace(raw, []byte(`"goal":"pay"`), []byte(`"goal":"PAY"`), 1)
	if bytes.Equal(raw, edited) {
		t.Fatal("test edit did not apply")
	}
	_ = os.WriteFile(path, edited, 0o600)
	if rep := NewEventStore(path).Verify(); rep.OK || rep.Reason != "an event was modified" {
		t.Fatalf("edit not detected: %+v", rep)
	}
}

func TestHeadsAreSeparatePerMission(t *testing.T) {
	s := NewEventStore("")
	a := s.Append("E", "a", map[string]any{})
	b := s.Append("E", "b", map[string]any{})
	if a.Prev != "" || b.Prev != "" || s.Head("a") != a.Hash || s.Head("b") != b.Hash || a.Hash == b.Hash {
		t.Fatal("chains must be independent per mission")
	}
}

func TestChainDoesNotBreakOnCyclicOrNonFinitePayloads(t *testing.T) {
	s := NewEventStore("")
	cyc := map[string]any{}
	cyc["self"] = cyc
	s.Append("E", "m", cyc)
	s.Append("E", "m", map[string]any{"x": math.NaN()})
	if rep := s.Verify(); !rep.OK {
		t.Fatalf("%+v", rep)
	}
}

func TestInputsDigestVectors(t *testing.T) {
	var doc struct {
		Cases []struct {
			Name          string         `json:"name"`
			Inputs        map[string]any `json:"inputs"`
			InputsSha256  string         `json:"inputs_sha256"`
			RuntimeDigest string         `json:"runtime_inputs_digest"`
		} `json:"cases"`
	}
	decodeNumbers(t, loadVectors(t, "inputs_digest.json"), &doc)
	for _, c := range doc.Cases {
		if got := InputsHash(c.Inputs); got != c.InputsSha256 {
			t.Errorf("%s inputs_sha256 %s want %s", c.Name, got, c.InputsSha256)
		}
		if got := RuntimeInputsDigest(c.Inputs); got != c.RuntimeDigest {
			t.Errorf("%s runtime digest %s want %s", c.Name, got, c.RuntimeDigest)
		}
	}
}

func TestActionSummaryVectors(t *testing.T) {
	var doc struct {
		Cases []struct {
			Name     string         `json:"name"`
			Resolved map[string]any `json:"resolved"`
			Summary  map[string]any `json:"summary"`
		} `json:"cases"`
	}
	decodeNumbers(t, loadVectors(t, "action_summary.json"), &doc)
	for _, c := range doc.Cases {
		got := ActionSummaryOf(c.Resolved)
		gb, _ := json.Marshal(got)
		wb, _ := json.Marshal(c.Summary)
		if string(gb) != string(wb) { // json.Marshal sorts map keys: a stable comparison
			t.Errorf("%s:\n go: %s\n py: %s", c.Name, gb, wb)
		}
	}
}

func TestApprovalTTLVectors(t *testing.T) {
	var doc struct {
		Cases []struct {
			ParkedAt *float64 `json:"parked_at"`
			Now      float64  `json:"now"`
			TTL      float64  `json:"ttl_s"`
			Expired  bool     `json:"expired"`
		} `json:"cases"`
	}
	decodeNumbers(t, loadVectors(t, "approval_ttl.json"), &doc)
	for i, c := range doc.Cases {
		if got := ApprovalExpired(c.ParkedAt, c.Now, c.TTL); got != c.Expired {
			t.Errorf("case %d: got %v want %v", i, got, c.Expired)
		}
	}
}

func TestAssuranceVectors(t *testing.T) {
	var doc struct {
		Cases []struct {
			Name    string `json:"name"`
			Now     float64
			Options struct {
				SideEffecting []string `json:"side_effecting"`
			} `json:"options"`
			Events   []json.RawMessage  `json:"events"`
			Findings []AssuranceFinding `json:"findings"`
		} `json:"cases"`
	}
	decodeNumbers(t, loadVectors(t, "assurance.json"), &doc)
	var raw struct {
		Cases []struct {
			Now float64 `json:"now"`
		} `json:"cases"`
	}
	decodeNumbers(t, loadVectors(t, "assurance.json"), &raw)
	for i, c := range doc.Cases {
		var evs []*Event
		for _, r := range c.Events {
			evs = append(evs, eventFromVector(t, r))
		}
		o := DefaultAssuranceOptions()
		if c.Options.SideEffecting != nil {
			o.SideEffecting = map[string]bool{}
			for _, s := range c.Options.SideEffecting {
				o.SideEffecting[s] = true
			}
		}
		got := AssuranceFindings(evs, raw.Cases[i].Now, o)
		gb, _ := json.Marshal(got)
		wb, _ := json.Marshal(c.Findings)
		if string(gb) != string(wb) {
			t.Errorf("%s:\n go: %s\n py: %s", c.Name, gb, wb)
		}
	}
}

func TestAssuranceFlagsATamperedLogAsCritical(t *testing.T) {
	s := NewEventStore("")
	s.Append("MissionCreated", "m", map[string]any{"goal": "pay"})
	s.Append("NodeSucceeded", "m", map[string]any{"node_id": "n", "capability": "x", "result": map[string]any{"amount": 100}})
	s.events[1].Payload["result"] = map[string]any{"amount": 1} // edit history in place
	var found bool
	for _, f := range AssuranceFindings(s.All(), now(), DefaultAssuranceOptions()) {
		if f.Kind == "ledger_tampered" && f.Severity == "critical" {
			found = true
		}
	}
	if !found {
		t.Fatal("ledger_tampered not reported")
	}
}
